-- Fixed series/date caller profiles;synthetic values only.
DECLARE @ExpectedApiCount int=9;
INSERT @Apis VALUES
(1,N'toolbelt_core',N'TVF_GenerateSeriesBigInt','SELECT',N'SELECT * FROM toolbelt_core.TVF_GenerateSeriesBigInt(-3,3,2);',N'DECLARE @Rows table(Value bigint NULL); INSERT @Rows SELECT Value FROM toolbelt_core.TVF_GenerateSeriesBigInt(-3,3,2); IF (SELECT COUNT(*) FROM @Rows)<>4 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=-3) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=-1) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=1) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=3) THROW 52097,N''Series/date fixed set oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_core.TVF_GenerateSeriesBigInt(NULL,3,1); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date NULL oracle.'',13; DECLARE @ZeroObserved bit=0,@ZeroCount bigint; SET @ZeroObserved=0; BEGIN TRY EXEC sys.sp_executesql N''SELECT @n=COUNT_BIG(*) FROM toolbelt_core.TVF_GenerateSeriesBigInt(1,3,0);'',N''@n bigint OUTPUT'',@n=@ZeroCount OUTPUT; END TRY BEGIN CATCH IF ERROR_NUMBER()<>8134 THROW; SET @ZeroObserved=1; END CATCH; IF @ZeroObserved=0 THROW 52097,N''Series/date exact zero-step engine oracle.'',14; SET @ZeroObserved=0; BEGIN TRY EXEC sys.sp_executesql N''SELECT @n=COUNT_BIG(*) FROM toolbelt_core.TVF_GenerateSeriesBigInt(NULL,3,0);'',N''@n bigint OUTPUT'',@n=@ZeroCount OUTPUT; END TRY BEGIN CATCH IF ERROR_NUMBER()<>8134 THROW; SET @ZeroObserved=1; END CATCH; IF @ZeroObserved=0 THROW 52097,N''Series/date exact zero-step engine oracle.'',14;  DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_core.TVF_GenerateSeriesBigInt(CONVERT(bigint,''-9223372036854775808''),CONVERT(bigint,''-9223372036854775806''),1); IF (SELECT COUNT(*) FROM @Rows)<>3 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(bigint,''-9223372036854775808'')) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(bigint,''-9223372036854775807'')) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(bigint,''-9223372036854775806'')) THROW 52097,N''Series/date bigint boundary oracle.'',15;'),
(2,N'toolbelt_core',N'TVF_GenerateSeriesInt','SELECT',N'SELECT * FROM toolbelt_core.TVF_GenerateSeriesInt(3,-3,-2);',N'DECLARE @Rows table(Value int NULL); INSERT @Rows SELECT Value FROM toolbelt_core.TVF_GenerateSeriesInt(3,-3,-2); IF (SELECT COUNT(*) FROM @Rows)<>4 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=3) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=1) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=-1) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=-3) THROW 52097,N''Series/date fixed set oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_core.TVF_GenerateSeriesInt(NULL,3,1); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date NULL oracle.'',13; DECLARE @ZeroObserved bit=0,@ZeroCount bigint; SET @ZeroObserved=0; BEGIN TRY EXEC sys.sp_executesql N''SELECT @n=COUNT_BIG(*) FROM toolbelt_core.TVF_GenerateSeriesInt(1,3,0);'',N''@n bigint OUTPUT'',@n=@ZeroCount OUTPUT; END TRY BEGIN CATCH IF ERROR_NUMBER()<>8134 THROW; SET @ZeroObserved=1; END CATCH; IF @ZeroObserved=0 THROW 52097,N''Series/date exact zero-step engine oracle.'',14; SET @ZeroObserved=0; BEGIN TRY EXEC sys.sp_executesql N''SELECT @n=COUNT_BIG(*) FROM toolbelt_core.TVF_GenerateSeriesInt(NULL,3,0);'',N''@n bigint OUTPUT'',@n=@ZeroCount OUTPUT; END TRY BEGIN CATCH IF ERROR_NUMBER()<>8134 THROW; SET @ZeroObserved=1; END CATCH; IF @ZeroObserved=0 THROW 52097,N''Series/date exact zero-step engine oracle.'',14; '),
(3,N'toolbelt_core',N'TVF_GenerateSeriesBigIntStatus','SELECT',N'SELECT * FROM toolbelt_core.TVF_GenerateSeriesBigIntStatus(-3,3,2);',N'DECLARE @Rows table(Value bigint NULL,Status varchar(16) NULL,RequestedRows decimal(38,0) NULL); INSERT @Rows SELECT Value,Status,RequestedRows FROM toolbelt_core.TVF_GenerateSeriesBigIntStatus(-3,3,2); IF (SELECT COUNT(*) FROM @Rows)<>4 OR EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL OR Value NOT IN(-3,-1,1,3) OR Status IS NULL OR Status<>''OK'' OR RequestedRows IS NULL OR RequestedRows<>4) OR (SELECT COUNT(DISTINCT Value) FROM @Rows)<>4 THROW 52097,N''Series status fixed oracle.'',16; DELETE @Rows; INSERT @Rows SELECT Value,Status,RequestedRows FROM toolbelt_core.TVF_GenerateSeriesBigIntStatus(NULL,3,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Status=''SQL_NULL'' AND RequestedRows IS NULL) THROW 52097,N''Series status sentinel oracle.'',17; DELETE @Rows; INSERT @Rows SELECT Value,Status,RequestedRows FROM toolbelt_core.TVF_GenerateSeriesBigIntStatus(1,3,0); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Status=''INVALID'' AND RequestedRows IS NULL) THROW 52097,N''Series status sentinel oracle.'',17; DELETE @Rows; INSERT @Rows SELECT Value,Status,RequestedRows FROM toolbelt_core.TVF_GenerateSeriesBigIntStatus(3,1,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Status=''EMPTY'' AND RequestedRows=0) THROW 52097,N''Series status sentinel oracle.'',17; DELETE @Rows; INSERT @Rows SELECT Value,Status,RequestedRows FROM toolbelt_core.TVF_GenerateSeriesBigIntStatus(1,1000001,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Status=''LIMIT'' AND RequestedRows=1000001) THROW 52097,N''Series status sentinel oracle.'',17;'),
(4,N'toolbelt_datetime',N'TVF_DateSpineDay','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateSpineDay(''20240228'',''20240302'');',N'DECLARE @Rows table(Ordinal int NULL,PeriodStart date NULL);INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineDay(''20240228'',''20240302'');IF (SELECT COUNT(*) FROM @Rows)<>3 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=0 AND PeriodStart=CONVERT(date,''20240228'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=1 AND PeriodStart=CONVERT(date,''20240229'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=2 AND PeriodStart=CONVERT(date,''20240301'',112)) THROW 52097,N''Series/date period set oracle.'',18; DELETE @Rows; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineDay(NULL,NULL); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date empty NULL oracle.'',19; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineDay(''20260101'',''20260101''); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date empty range oracle.'',20; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineDay(''20260102'',''20260101''); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date reversed range oracle.'',21;'),
(5,N'toolbelt_datetime',N'TVF_DateSpineMonth','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateSpineMonth(''20260115'',''20260402'');',N'DECLARE @Rows table(Ordinal int NULL,PeriodStart date NULL);INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineMonth(''20260115'',''20260402'');IF (SELECT COUNT(*) FROM @Rows)<>4 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=0 AND PeriodStart=CONVERT(date,''20260101'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=1 AND PeriodStart=CONVERT(date,''20260201'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=2 AND PeriodStart=CONVERT(date,''20260301'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=3 AND PeriodStart=CONVERT(date,''20260401'',112)) THROW 52097,N''Series/date period set oracle.'',18; DELETE @Rows; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineMonth(NULL,NULL); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date empty NULL oracle.'',19; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineMonth(''20260101'',''20260101''); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date empty range oracle.'',20; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineMonth(''20260102'',''20260101''); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date reversed range oracle.'',21;'),
(6,N'toolbelt_datetime',N'TVF_DateSpineIsoWeek','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateSpineIsoWeek(''20251231'',''20260108'');',N'DECLARE @Rows table(Ordinal int NULL,PeriodStart date NULL); DECLARE @SavedDateFirst int=@@DATEFIRST; SET DATEFIRST 7;INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineIsoWeek(''20251231'',''20260108'');IF (SELECT COUNT(*) FROM @Rows)<>2 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=0 AND PeriodStart=CONVERT(date,''20251229'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=1 AND PeriodStart=CONVERT(date,''20260105'',112)) THROW 52097,N''Series/date period set oracle.'',18; DELETE @Rows; SET DATEFIRST 3;INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineIsoWeek(''20251231'',''20260108'');IF (SELECT COUNT(*) FROM @Rows)<>2 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=0 AND PeriodStart=CONVERT(date,''20251229'',112)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=1 AND PeriodStart=CONVERT(date,''20260105'',112)) THROW 52097,N''Series/date period set oracle.'',18; SET DATEFIRST @SavedDateFirst; DELETE @Rows; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineIsoWeek(NULL,NULL); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date empty NULL oracle.'',19; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineIsoWeek(''20260101'',''20260101''); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date empty range oracle.'',20; INSERT @Rows SELECT Ordinal,PeriodStart FROM toolbelt_datetime.TVF_DateSpineIsoWeek(''20260102'',''20260101''); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Series/date reversed range oracle.'',21;'),
(7,N'toolbelt_datetime',N'TVF_TruncateDate','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_TruncateDate(''month'',''20260730'');',N'DECLARE @Rows table(Value date NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDate(''month'',''20260730''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(date,''20260701'') AND IsValid=1 AND ValidationCode=0) THROW 52097,N''Series/date truncate fixed oracle.'',22; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDate(''month'',NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''Series/date truncate NULL oracle.'',23; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDate(''bogus'',''20260730''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=10) THROW 52097,N''Series/date truncate invalid oracle.'',24;'),
(8,N'toolbelt_datetime',N'TVF_TruncateDateTime2','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_TruncateDateTime2(''millisecond'',''2026-07-30T12:34:56.1234567'');',N'DECLARE @Rows table(Value datetime2(7) NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDateTime2(''millisecond'',''2026-07-30T12:34:56.1234567''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(datetime2(7),''2026-07-30T12:34:56.1230000'') AND IsValid=1 AND ValidationCode=0) THROW 52097,N''Series/date truncate fixed oracle.'',22; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDateTime2(''millisecond'',NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''Series/date truncate NULL oracle.'',23; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDateTime2(''bogus'',''2026-07-30T12:34:56.1234567''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=10) THROW 52097,N''Series/date truncate invalid oracle.'',24;'),
(9,N'toolbelt_datetime',N'TVF_TruncateDateTimeOffset','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_TruncateDateTimeOffset(''hour'',''2026-07-30T12:34:56.1234567+05:30'');',N'DECLARE @Rows table(Value datetimeoffset(7) NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDateTimeOffset(''hour'',''2026-07-30T12:34:56.1234567+05:30''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(datetimeoffset(7),''2026-07-30T12:00:00.0000000+05:30'') AND IsValid=1 AND ValidationCode=0 AND DATEPART(TZOFFSET,Value)=330) THROW 52097,N''Series/date truncate fixed oracle.'',22; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDateTimeOffset(''hour'',NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''Series/date truncate NULL oracle.'',23; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_TruncateDateTimeOffset(''bogus'',''2026-07-30T12:34:56.1234567+05:30''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=10) THROW 52097,N''Series/date truncate invalid oracle.'',24;');
INSERT @Denied VALUES
